const body = $input.first().json.body || {};

// Validate required fields
const query = body.query;
const context = body.context || {};
const pluginContext = body.plugin_context || {};
const apiKey = pluginContext.api_keys?.anthropic;

const errors = [];
if (!query || query.trim() === '') errors.push('query requis');
if (!context.type) errors.push('context.type requis');
if (!apiKey) errors.push('plugin_context.api_keys.anthropic requis');

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  };
}

// Extract config with defaults
const minScore = context.min_score || 0.7;
const allowedIntents = context.allowed_intents || ['search', 'info', 'help'];
const llmModel = pluginContext.llm_model || 'claude-3-haiku-20240307';
// auto_web_search: true by default (backwards compatible)
const autoWebSearch = context.auto_web_search !== false;

return {
  json: {
    valid: true,
    query: query.trim(),
    context: {
      type: context.type,
      allowed_intents: allowedIntents,
      min_score: minScore,
      auto_web_search: autoWebSearch
    },
    plugin_context: pluginContext,
    llm_model: llmModel,
    api_key: apiKey,
    user: body.user || {}
  }
};

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const statusCode = input.statusCode || 200;

// Handle LLM API error
if (statusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: input.body?.error?.message || 'LLM API error',
        status: 'LLM_ERROR'
      }
    }
  };
}

// Extract LLM response
const content = input.body?.content?.[0]?.text || '';

// Parse JSON from LLM response
let analysis;
try {
  // Try to extract JSON from the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  // Default analysis if parsing fails
  analysis = {
    is_relevant: true,
    intent: 'search',
    extracted_terms: prevData.query,
    detected_language: 'fr',
    spelling_corrected: false,
    confidence: 0.5,
    rejection_reason: null
  };
}

return {
  json: {
    success: true,
    analysis: analysis,
    original_query: prevData.query,
    context: prevData.context,
    plugin_context: prevData.plugin_context,
    user: prevData.user
  }
};

const input = $input.first().json;

return {
  json: {
    success: true,
    is_relevant: false,
    intent: {
      type: 'out_of_context',
      confidence: input.analysis.confidence || 0
    },
    query_analysis: {
      original: input.original_query,
      reformulation: input.analysis.reformulation || input.original_query,
      extracted_terms: input.analysis.extracted_terms || '',
      spelling_corrected: input.analysis.spelling_corrected || false,
      detected_language: input.analysis.detected_language || 'unknown'
    },
    qdrant: {
      searched: false,
      results: [],
      best_score: 0,
      above_threshold: false
    },
    next_action: 'reject',
    message: input.analysis.rejection_reason || `Cette requête ne concerne pas le contexte ${input.context.type}.`
  }
};

const qdrantResponse = $input.first().json;
const prevData = $('Parse LLM Response').first().json;

// Extract Qdrant results
const qdrantBody = qdrantResponse.body || qdrantResponse;
const qdrantSuccess = qdrantBody.success !== false;
const qdrantResults = qdrantBody.data?.results || [];

// Find best score
let bestScore = 0;
if (qdrantResults.length > 0) {
  bestScore = Math.max(...qdrantResults.map(r => r.score || 0));
}

// Check against threshold
const minScore = prevData.context.min_score || 0.7;
const aboveThreshold = bestScore >= minScore;

// Check auto_web_search setting (true by default)
const autoWebSearch = prevData.context.auto_web_search !== false;

// Determine next action
let nextAction;
let message;

if (qdrantResults.length === 0) {
  // No results - propose or auto search based on setting
  if (autoWebSearch) {
    nextAction = 'web_search';
    message = `Aucun résultat trouvé pour "${prevData.analysis.extracted_terms}". Recherche web en cours...`;
  } else {
    nextAction = 'propose_web_search';
    message = `Aucun résultat trouvé pour "${prevData.analysis.extracted_terms}". Voulez-vous chercher sur le web ?`;
  }
} else if (aboveThreshold) {
  nextAction = 'return_results';
  message = null;
} else {
  // Results below threshold - propose or auto search based on setting
  if (autoWebSearch) {
    nextAction = 'web_search';
    message = `Résultats peu pertinents (score: ${Math.round(bestScore * 100)}%). Recherche web en cours...`;
  } else {
    nextAction = 'propose_web_search';
    message = `Résultats peu pertinents (score: ${Math.round(bestScore * 100)}%). Voulez-vous chercher sur le web ?`;
  }
}

return {
  json: {
    success: true,
    is_relevant: true,
    intent: {
      type: prevData.analysis.intent,
      confidence: prevData.analysis.confidence
    },
    query_analysis: {
      original: prevData.original_query,
      reformulation: prevData.analysis.reformulation || prevData.original_query,
      extracted_terms: prevData.analysis.extracted_terms,
      spelling_corrected: prevData.analysis.spelling_corrected,
      detected_language: prevData.analysis.detected_language
    },
    qdrant: {
      searched: true,
      results: qdrantResults,
      best_score: bestScore,
      above_threshold: aboveThreshold
    },
    next_action: nextAction,
    message: message
  }
};

